<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { type PaymentIdentifierPolicy, type PaymentIdentifierCapabilities } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
import { useI18n } from "vue-i18n";
const { t } = useI18n();
const props=defineProps<{modelValue:PaymentIdentifierPolicy|null;capabilities:PaymentIdentifierCapabilities}>();
const emit=defineEmits<{"update:modelValue":[value:PaymentIdentifierPolicy|null];valid:[value:boolean]}>();
const enabled=ref(false),mode=ref<PaymentIdentifierPolicy["mode"]>("exact_requested"),adjustment=ref(""),step=ref("");
watch(()=>props.modelValue,value=>{enabled.value=value!==null;mode.value=value?.mode??"exact_requested";adjustment.value=value?String(value.max_adjustment_rial):"";step.value=value?String(value.amount_step_rial):"";},{immediate:true});
const valid=computed(()=>!enabled.value||Boolean(adjustment.value&&step.value&&Number.isSafeInteger(Number(adjustment.value))&&Number(adjustment.value)>=0&&Number.isSafeInteger(Number(step.value))&&Number(step.value)>0&&props.capabilities.suffix_modulus%Number(step.value)===0&&props.capabilities.supported_modes.includes(mode.value)&&(mode.value!=="rial_suffix4"||props.capabilities.capacity&&Number(adjustment.value)<=props.capabilities.capacity.max_adjustment_rial&&Math.floor(Number(adjustment.value)/Number(step.value))+1<=props.capabilities.capacity.max_candidate_amounts)));
watch(valid,value=>emit("valid",value),{immediate:true});
function apply():void{if(!enabled.value){emit("update:modelValue",null);return;}if(!valid.value)return;emit("update:modelValue",{mode:mode.value,max_adjustment_rial:Number(adjustment.value),amount_step_rial:Number(step.value)});}
</script>
<template><section class="form-grid" :aria-label="t('settingsEditors.identifier.title')"><h4>{{t('settingsEditors.identifier.title')}}</h4><p>{{t('settingsEditors.identifier.description')}}</p><p v-if="capabilities.capacity===null" class="hint-box" role="status">{{t('settingsEditors.identifier.unavailable')}}</p><dl v-else><dt>{{t('settingsEditors.identifier.maxAdjustment')}}</dt><dd>{{capabilities.capacity.max_adjustment_rial}} RIAL</dd><dt>{{t('settingsEditors.identifier.candidates')}}</dt><dd>{{capabilities.capacity.max_candidate_amounts}}</dd><dt>{{t('settingsEditors.identifier.active')}}</dt><dd>{{capabilities.capacity.max_active_codes}}</dd></dl><label class="check-row"><input v-model="enabled" type="checkbox" @change="apply"/>{{t('settingsEditors.identifier.enable')}}</label><template v-if="enabled"><label class="field"><span>{{t('settingsEditors.identifier.mode')}}</span><select v-model="mode" @change="apply"><option v-for="value in capabilities.supported_modes" :key="value" :value="value" :disabled="value==='rial_suffix4'&&capabilities.capacity===null">{{t(`settingsEditors.identifier.${value==='exact_requested'?'exact':'suffix'}`)}}</option></select></label><NumField v-model="adjustment" :label="t('settingsEditors.identifier.adjustment')" @update:model-value="apply"/><NumField v-model="step" :label="t('settingsEditors.identifier.step')" @update:model-value="apply"/><p>{{t('settingsEditors.identifier.stepHint',{modulus:capabilities.suffix_modulus,digits:capabilities.suffix_digits})}}</p><p v-if="!valid" class="message error" role="alert">{{t('settingsEditors.identifier.invalid')}}</p></template></section></template>
